window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4bcc111cb1a31287"]={"versions": [{"id": "FIG-4bcc111cb1a31287", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4m). Das Diagramm visualisiert den sequenziellen Prüfschritt „Verify inputs of the protect function“ vor der eigentlichen Berechnung und Modifikation der Übertragungsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext:</strong> Funktion <code>E2E_P04mProtect()</code>.</li>\n<li><strong>Eingangsparameter & Prüfentitäten:</strong></li>\n<li><code>Config</code>: Zeiger auf die statische Profil-Konfigurationsstruktur (u. a. <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur der Schutzfunktion.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Payload-Array.</li>\n<li><code>Length</code>: Länge des zu schützenden Nutzdatenbereichs in Bytes.</li>\n<li><code>SourceID</code>: 32-Bit-Quellidentifikator (darf maximal <code>0xFFFFFFF</code>, also 28 Bit, belegen).</li>\n<li><code>MessageType</code>: Nachrichtentyp (Wertebereich 0 bis 1).</li>\n<li><code>MessageResult</code>: Nachrichtenübertragungsergebnis (Wertebereich 0 bis 1).</li>\n<li><strong>Ablaufelemente & Endzustände:</strong></li>\n<li>Startknoten (Initial Node).</li>\n<li>Fünf Entscheidungsknoten (Decision Diamonds) mit <code>[TRUE]</code>- und <code>[FALSE]</code>-Guards.</li>\n<li>Drei Ablaufendknoten (Activity Final Nodes): <code>null input</code>, <code>wrong input</code> und <code>input ok</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>null input</code> (Zeiger ungültig).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung der Datenlänge:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Quellidentifikators:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>SourceID &lt;= 0xFFFFFFF</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Nachrichtentyps:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(MessageType &gt;= 0) &amp;&amp; (MessageType &lt;= 1)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Nachrichtenergebnisses:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(MessageResult &gt;= 0) &amp;&amp; (MessageResult &lt;= 1)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Werden alle Bedingungen mit <code>[TRUE]</code> evaluiert, erreicht der Kontrollfluss den Endknoten <code>input ok</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Fehlerbehandlungsverhalten gemäß Anforderung <code>[PRS_E2E_00757]</code>. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\">\n<li>Zeigerprüfungen (<code>NULL</code>) besitzen strikte Priorität und führen direkt zur Klassifikation als Null-Eingabe (<code>null input</code> bzw. Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Längen- und Wertebereichsverletzungen führen unmittelbar zu <code>wrong input</code> (<code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bit spezifiziert und müssen vor dem Vergleich mit <code>Length</code> ganzzahlig durch 8 dividiert werden.</li>\n<li>Die Prüfungen brechen kaskadierend beim ersten Fehler ab (Short-Circuit-Verhalten im Aktivitätsfluss).</li>\n</ul>"}, {"id": "FIG-7850640e8b01b547", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der E2E-Bibliotheksfunktion <code>E2E_P04mProtect()</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 4m). Das Diagramm visualisiert den sequenziellen Prüfschritt „Verify inputs of the protect function“ vor der eigentlichen Berechnung und Modifikation der Übertragungsdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext:</strong> Funktion <code>E2E_P04mProtect()</code>.</li>\n<li><strong>Eingangsparameter & Prüfentitäten:</strong></li>\n<li><code>Config</code>: Zeiger auf die statische Profil-Konfigurationsstruktur (u. a. <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur der Schutzfunktion.</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Payload-Array.</li>\n<li><code>Length</code>: Länge des zu schützenden Nutzdatenbereichs in Bytes.</li>\n<li><code>SourceID</code>: 32-Bit-Quellidentifikator (darf maximal <code>0xFFFFFFF</code>, also 28 Bit, belegen).</li>\n<li><code>MessageType</code>: Nachrichtentyp (Wertebereich 0 bis 1).</li>\n<li><code>MessageResult</code>: Nachrichtenübertragungsergebnis (Wertebereich 0 bis 1).</li>\n<li><strong>Ablaufelemente & Endzustände:</strong></li>\n<li>Startknoten (Initial Node).</li>\n<li>Fünf Entscheidungsknoten (Decision Diamonds) mit <code>[TRUE]</code>- und <code>[FALSE]</code>-Guards.</li>\n<li>Drei Ablaufendknoten (Activity Final Nodes): <code>null input</code>, <code>wrong input</code> und <code>input ok</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Startknoten in den ersten Entscheidungsknoten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>null input</code> (Zeiger ungültig).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung der Datenlänge:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Quellidentifikators:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>SourceID &lt;= 0xFFFFFFF</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Nachrichtentyps:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(MessageType &gt;= 0) &amp;&amp; (MessageType &lt;= 1)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> Prüfung des Nachrichtenergebnisses:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bedingung: <code>(MessageResult &gt;= 0) &amp;&amp; (MessageResult &lt;= 1)</code>.</li>\n<li>Bei <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Werden alle Bedingungen mit <code>[TRUE]</code> evaluiert, erreicht der Kontrollfluss den Endknoten <code>input ok</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Fehlerbehandlungsverhalten gemäß Anforderung <code>[PRS_E2E_00757]</code>. Für Implementierer ist zu beachten:</p>\n<ul class=\"fig-list\">\n<li>Zeigerprüfungen (<code>NULL</code>) besitzen strikte Priorität und führen direkt zur Klassifikation als Null-Eingabe (<code>null input</code> bzw. Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Längen- und Wertebereichsverletzungen führen unmittelbar zu <code>wrong input</code> (<code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bit spezifiziert und müssen vor dem Vergleich mit <code>Length</code> ganzzahlig durch 8 dividiert werden.</li>\n<li>Die Prüfungen brechen kaskadierend beim ersten Fehler ab (Short-Circuit-Verhalten im Aktivitätsfluss).</li>\n</ul>"}], "trans": [{"from": "FIG-4bcc111cb1a31287", "to": "FIG-7850640e8b01b547", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
